// 2nd-order IIR section in fixed point
typedef ap_fixed<32, 8, AP_RND_CONV, AP_SAT> acc_t;
acc_t biquad(ap_fixed<16,2> x) {
#pragma HLS PIPELINE II=1
  static acc_t z1 = 0, z2 = 0;
  acc_t y = b0 * x + z1;
  z1 = b1 * x - a1 * y + z2;
  z2 = b2 * x - a2 * y;
  return y;
}

