// Burst-friendly copy
void k(const int *in, int *out, int n) {
#pragma HLS INTERFACE m_axi port=in bundle=gmem0 max_read_burst_length=256 num_read_outstanding=8 latency=64
#pragma HLS INTERFACE m_axi port=out bundle=gmem1 max_write_burst_length=256
  int buf[1024];
  for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    buf[i] = in[i];              // sequential -> burst
  }
  process(buf, n);
  for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    out[i] = buf[i];
  }
}
// Float accumulation at II=1 with partial sums
float sum(const float *x, int n) {
  float part[8] = {0};
#pragma HLS ARRAY_PARTITION variable=part complete
  for (int i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    part[i % 8] += x[i];         // each partial sum updated every 8 cycles
  }
  float s = 0; for (int j = 0; j < 8; j++) s += part[j];
  return s;
}
